// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        vm.prank(caller1);
        address result1 = c.owner();
        vm.prank(caller2);
        address result2 = c.owner();
        assertTrue(result1 == result2);
    }
}
